import React, { useState, useEffect, useRef } from 'react';
import {
  Box,
  Typography,
  TextField,
  Alert,
  IconButton,
  useTheme,
  useMediaQuery,
} from '@mui/material';
import {
  RecordVoiceOver,
  Add,
  Delete,
  Image as ImageIcon,
  VideoLibrary,
} from '@mui/icons-material';
import {
  ElevenLabsButton,
  ElevenLabsFileUpload,
  ElevenLabsTabs,
  SettingSelect,
  SettingToggle,
  ElevenLabsSettingsPanel,
  SettingSection,
  PropertySection,
  PropertyRow,
  StudioPlayerBar,
} from '../ElevenLabsUI';
import StudioPageShell from '../Layout/StudioPageShell';
import StudioHistorySection from '../Layout/StudioHistorySection';
import { ttsAPI, videoAPI, getFriendlyErrorMessage, BASE_URL } from '../../services/api';
import { NEURAL_LANGUAGES, NEURAL_SPEAKERS } from '../../constants/neural_config';
import useStudioUser from '../../hooks/useStudioUser';
import { StudioJobProgressBar } from '../progress';

const MODES = [
  { label: 'Narration', icon: <RecordVoiceOver fontSize="small" /> },
  { label: 'Slideshow', icon: <ImageIcon fontSize="small" /> },
];

const newBlock = (lang, voice) => ({
  id: Date.now() + Math.random(),
  text: '',
  voice: voice || NEURAL_SPEAKERS[0].id,
  language: lang || NEURAL_SPEAKERS[0].lang,
  pitch: 0,
  rate: 1.0,
});

export default function VoiceoverElevenLabs({ userId: userIdProp }) {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const { userId: hookUserId, balance, refreshBalance } = useStudioUser();
  const userId = userIdProp || hookUserId;

  const [mode, setMode] = useState(0);
  const [blocks, setBlocks] = useState([newBlock()]);
  const [selectedLang, setSelectedLang] = useState(NEURAL_SPEAKERS[0].lang);
  const [selectedVoice, setSelectedVoice] = useState(NEURAL_SPEAKERS[0].id);
  const [videoFile, setVideoFile] = useState(null);
  const [imageFiles, setImageFiles] = useState([]);
  const [bgmEnabled, setBgmEnabled] = useState(false);
  const [bgmTracks, setBgmTracks] = useState([]);
  const [selectedBgm, setSelectedBgm] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [combinedAudioUrl, setCombinedAudioUrl] = useState(null);
  const [outputVideoUrl, setOutputVideoUrl] = useState(null);
  const slideshowPollRef = useRef(null);

  const stopPoll = () => {
    if (slideshowPollRef.current) {
      clearInterval(slideshowPollRef.current);
      slideshowPollRef.current = null;
    }
  };

  useEffect(() => () => stopPoll(), []);

  useEffect(() => {
    videoAPI
      .getBgmTracks()
      .then((data) => {
        const tracks = data?.tracks?.length ? data.tracks : [];
        setBgmTracks(tracks);
        if (tracks[0]) setSelectedBgm(tracks[0].id);
      })
      .catch(() => setBgmTracks([]));
  }, []);

  const updateBlock = (id, patch) => {
    setBlocks((prev) => prev.map((b) => (b.id === id ? { ...b, ...patch } : b)));
  };

  const addBlock = () => setBlocks((prev) => [...prev, newBlock(selectedLang, selectedVoice)]);
  const removeBlock = (id) => {
    if (blocks.length <= 1) return;
    setBlocks((prev) => prev.filter((b) => b.id !== id));
  };

  const pollSlideshowJob = (jobId) =>
    new Promise((resolve, reject) => {
      let attempts = 0;
      slideshowPollRef.current = setInterval(async () => {
        attempts += 1;
        if (attempts > 240) {
          stopPoll();
          reject(new Error('Render timed out'));
          return;
        }
        try {
          const job = await videoAPI.getJobStatus(jobId);
          if (job.status === 'completed' && job.result?.slideshow_url) {
            stopPoll();
            resolve(job.result.slideshow_url);
          } else if (job.status === 'error' || job.status === 'failed') {
            stopPoll();
            reject(new Error(job.error || 'Slideshow failed'));
          }
        } catch {
          /* retry */
        }
      }, 2000);
    });

  const handleGenerate = async () => {
    if (!userId) {
      setError('Please log in to continue');
      return;
    }

    const populated = blocks.filter((b) => b.text.trim());
    if (!populated.length) {
      setError('Add at least one script block with text');
      return;
    }

    setLoading(true);
    setError(null);
    setCombinedAudioUrl(null);
    setOutputVideoUrl(null);

    try {
      if (mode === 1) {
        if (!imageFiles.length) throw new Error('Upload at least one image');
        if (populated.length < imageFiles.length) {
          throw new Error('Add a script block for each image');
        }
        const segments = populated.slice(0, imageFiles.length).map((b) => ({
          text: b.text,
          speaker_id: b.voice || selectedVoice,
          target_lang: b.language || selectedLang,
          pitch: b.pitch,
          rate: b.rate,
        }));
        const res = await videoAPI.finalizeImageSlideshow(segments, userId, imageFiles, {
          bgmTrack: bgmEnabled ? selectedBgm : null,
        });
        let url = res.slideshow_url;
        if (res.job_id) url = await pollSlideshowJob(res.job_id);
        setOutputVideoUrl(url);
      } else {
        const res = await ttsAPI.renderVoiceover(
          populated.map((b) => ({
            text: b.text,
            speaker_id: b.voice || selectedVoice,
            language: b.language || selectedLang,
            pitch: b.pitch,
            rate: b.rate,
          })),
          userId,
          `Narration – ${new Date().toLocaleString()}`,
          bgmEnabled ? selectedBgm : null
        );

        if (res.combined_audio_url) setCombinedAudioUrl(res.combined_audio_url);

        if (videoFile && res.doc_id) {
          const videoRes = await videoAPI.finalizeNarrationVideo(res.doc_id, userId, videoFile, {
            bgmTrack: bgmEnabled ? selectedBgm : null,
          });
          if (videoRes.narration_video_url) setOutputVideoUrl(videoRes.narration_video_url);
        }
      }

      refreshBalance();
      window.dispatchEvent(new CustomEvent('refresh-balance'));
      window.dispatchEvent(new CustomEvent('library-updated'));
    } catch (e) {
      setError(getFriendlyErrorMessage(e, 'Generation failed'));
    } finally {
      setLoading(false);
    }
  };

  const langOptions = NEURAL_LANGUAGES.filter((l) => l.code !== 'all').map((l) => ({
    value: l.code,
    label: l.name,
  }));

  const voicesForLang = NEURAL_SPEAKERS.filter((s) => s.lang === selectedLang);

  const settingsContent = (
    <ElevenLabsSettingsPanel sx={{ border: 'none', boxShadow: 'none', borderRadius: 0 }}>
      <SettingSection title="Voice">
        <SettingSelect
          label="Language"
          value={selectedLang}
          onChange={(e) => {
            setSelectedLang(e.target.value);
            const match = NEURAL_SPEAKERS.find((s) => s.lang === e.target.value);
            if (match) {
              setSelectedVoice(match.id);
              setBlocks((prev) => prev.map((b) => ({ ...b, language: e.target.value, voice: match.id })));
            }
          }}
          options={langOptions}
        />
        <SettingSelect
          label="Speaker"
          value={selectedVoice}
          onChange={(e) => {
            setSelectedVoice(e.target.value);
            setBlocks((prev) => prev.map((b) => ({ ...b, voice: e.target.value })));
          }}
          options={(voicesForLang.length ? voicesForLang : NEURAL_SPEAKERS).map((v) => ({
            value: v.id,
            label: v.name,
          }))}
        />
      </SettingSection>
      {mode === 0 && (
        <SettingSection title="Video (optional)">
          <Typography sx={{ fontSize: '0.75rem', color: '#999', mb: 1 }}>
            Mux narration onto a video after generation
          </Typography>
          <ElevenLabsFileUpload
            onFileSelect={setVideoFile}
            selectedFile={videoFile}
            onClearFile={() => setVideoFile(null)}
            accept="video/*"
          />
        </SettingSection>
      )}
      {bgmTracks.length > 0 && (
        <SettingSection title="Background music">
          <SettingToggle
            label="Add BGM"
            checked={bgmEnabled}
            onChange={(e) => setBgmEnabled(e.target.checked)}
          />
          {bgmEnabled && (
            <SettingSelect
              label="Track"
              value={selectedBgm}
              onChange={(e) => setSelectedBgm(e.target.value)}
              options={bgmTracks.map((t) => ({ value: t.id, label: t.name || t.id }))}
            />
          )}
        </SettingSection>
      )}
      <PropertySection title="Account" defaultOpen={false}>
        <PropertyRow label="Credits" value={balance !== null ? balance.toFixed(2) : '…'} />
        <PropertyRow label="Blocks" value={String(blocks.length)} />
      </PropertySection>
      <Box sx={{ px: 3, pb: 3 }}>
        <ElevenLabsButton
          variant="contained"
          fullWidth
          size="large"
          loading={loading}
          disabled={loading}
          onClick={handleGenerate}
        >
          {mode === 1 ? 'Generate slideshow' : 'Generate voiceover'}
        </ElevenLabsButton>
      </Box>
    </ElevenLabsSettingsPanel>
  );

  const speaker = NEURAL_SPEAKERS.find((s) => s.id === selectedVoice) || NEURAL_SPEAKERS[0];
  const playerUrl = combinedAudioUrl || (outputVideoUrl && !outputVideoUrl.endsWith('.mp4') ? outputVideoUrl : null);

  return (
    <>
      <StudioPageShell
        icon={<RecordVoiceOver sx={{ fontSize: 22 }} />}
        title="Voiceover"
        subtitle="Write a script, pick a voice, and generate narration or a slideshow video"
        maxWidth={1040}
        settingsContent={settingsContent}
        showPropertiesPanel={!isMobile}
        bottomBar={
          <StudioPlayerBar
            voiceName={speaker.name}
            voiceLang={speaker.lang}
            audioUrl={combinedAudioUrl}
            disabled={!combinedAudioUrl}
            onDownload={() => {
              if (!combinedAudioUrl) return;
              const link = document.createElement('a');
              link.href = combinedAudioUrl.startsWith('http') ? combinedAudioUrl : `${BASE_URL}${combinedAudioUrl}`;
              link.download = 'voiceover.mp3';
              link.target = '_blank';
              document.body.appendChild(link);
              link.click();
              document.body.removeChild(link);
            }}
          />
        }
      >
        <StudioJobProgressBar
          open={loading}
          message={mode === 1 ? 'Building slideshow…' : 'Synthesizing narration…'}
          submessage={mode === 1 ? 'Rendering images and audio' : 'Generating voice blocks'}
        />
        <Box sx={{ mb: 2 }}>
          <ElevenLabsTabs value={mode} onChange={(_, v) => setMode(v)} tabs={MODES} />
        </Box>

        {mode === 1 && (
          <Box sx={{ mb: 3 }}>
            <Typography sx={{ fontSize: '0.8125rem', fontWeight: 600, color: '#666', mb: 1 }}>
              Slideshow images ({imageFiles.length})
            </Typography>
            <Box
              component="label"
              sx={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 1,
                px: 2,
                py: 1,
                border: '1px dashed #e8e8e8',
                borderRadius: '10px',
                cursor: 'pointer',
                bgcolor: '#fafafa',
                fontSize: '0.875rem',
                fontWeight: 500,
                '&:hover': { borderColor: '#E8A020' },
              }}
            >
              <ImageIcon sx={{ fontSize: 18, color: '#E8A020' }} />
              Add images
              <input
                type="file"
                accept="image/*"
                multiple
                hidden
                onChange={(e) => {
                  const files = Array.from(e.target.files || []);
                  if (!files.length) return;
                  setImageFiles((prev) => [...prev, ...files]);
                  setBlocks((prev) => {
                    const total = imageFiles.length + files.length;
                    if (prev.length >= total) return prev;
                    const extra = Array.from({ length: total - prev.length }, () =>
                      newBlock(selectedLang, selectedVoice)
                    );
                    return [...prev, ...extra];
                  });
                  e.target.value = '';
                }}
              />
            </Box>
            {imageFiles.length > 0 && (
              <Box sx={{ mt: 1.5, display: 'flex', flexWrap: 'wrap', gap: 0.75 }}>
                {imageFiles.map((f, i) => (
                  <Typography key={`${f.name}-${i}`} sx={{ fontSize: '0.75rem', color: '#666', bgcolor: '#f5f5f5', px: 1, py: 0.5, borderRadius: '6px' }}>
                    {f.name}
                  </Typography>
                ))}
              </Box>
            )}
          </Box>
        )}

        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
          {blocks.map((block, index) => (
            <Box
              key={block.id}
              sx={{
                border: '1px solid #e8e8e8',
                borderRadius: '12px',
                p: 2,
                bgcolor: '#fff',
              }}
            >
              <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 1 }}>
                <Typography sx={{ fontSize: '0.75rem', fontWeight: 700, color: '#999' }}>
                  Block {index + 1}
                  {mode === 1 && imageFiles[index] ? ` · ${imageFiles[index].name}` : ''}
                </Typography>
                {blocks.length > 1 && (
                  <IconButton size="small" onClick={() => removeBlock(block.id)} sx={{ color: '#999' }}>
                    <Delete fontSize="small" />
                  </IconButton>
                )}
              </Box>
              <TextField
                multiline
                minRows={3}
                placeholder="Enter narration script…"
                value={block.text}
                onChange={(e) => updateBlock(block.id, { text: e.target.value })}
                fullWidth
                variant="standard"
                InputProps={{ disableUnderline: true }}
                sx={{
                  '& .MuiInputBase-root': { fontSize: '0.9375rem', lineHeight: 1.6 },
                }}
              />
            </Box>
          ))}
        </Box>

        <ElevenLabsButton
          variant="outlined"
          startIcon={<Add />}
          onClick={addBlock}
          sx={{ mt: 2, alignSelf: 'flex-start' }}
        >
          Add block
        </ElevenLabsButton>

        <StudioHistorySection sourceId="voiceover" />
      </StudioPageShell>

      {error && (
        <Alert severity="error" onClose={() => setError(null)} sx={{ position: 'fixed', bottom: 88, right: 24, zIndex: 9999, borderRadius: '8px' }}>
          {error}
        </Alert>
      )}
    </>
  );
}
