import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import {
  Box,
  Typography,
  TextField,
  Chip,
  Alert,
  MenuItem,
  useMediaQuery,
  useTheme,
} from '@mui/material';
import {
  VolumeUp,
  AutoStories,
  EmojiEmotions,
  Campaign,
  Language,
  Movie,
  Podcasts,
  SelfImprovement,
} from '@mui/icons-material';
import { StudioJobProgressBar } from './progress';
import { ttsAPI, getFriendlyErrorMessage } from '../services/api';
import { NEURAL_SPEAKERS, NEURAL_LANGUAGES } from '../constants/neural_config';
import useStudioUser from '../hooks/useStudioUser';
import StudioPageShell from './Layout/StudioPageShell';
import StudioHistorySection from './Layout/StudioHistorySection';
import {
  ElevenLabsButton,
  StudioPlayerBar,
  PropertySection,
  PropertyRow,
  ElevenLabsTextField,
  ElevenLabsFileUpload,
  SettingSelect,
  ElevenLabsSettingsPanel,
  SettingSection,
} from './ElevenLabsUI';

const TTS_RATE = 0.001;

const QUICK_PROMPTS = [
  { label: 'Narrate a story', icon: <AutoStories sx={{ fontSize: 16 }} />, text: 'Once upon a time, in a village nestled between rolling hills, there lived a storyteller whose words could bring the past to life...' },
  { label: 'Tell a silly joke', icon: <EmojiEmotions sx={{ fontSize: 16 }} />, text: 'Why did the scarecrow win an award? Because he was outstanding in his field!' },
  { label: 'Record an advertisement', icon: <Campaign sx={{ fontSize: 16 }} />, text: 'Introducing Avoices — natural AI voices for African languages. Transform your content with studio-quality speech.' },
  { label: 'Speak in different languages', icon: <Language sx={{ fontSize: 16 }} />, text: 'Hello! Habari! Nnọọ! Welcome to multilingual voice synthesis that sounds truly human.' },
  { label: 'Direct a dramatic scene', icon: <Movie sx={{ fontSize: 16 }} />, text: 'The rain hammered against the window. She turned slowly: "I knew you would come back."' },
  { label: 'Introduce your podcast', icon: <Podcasts sx={{ fontSize: 16 }} />, text: 'Welcome to The Voice Lab — where technology meets culture. Today we explore the future of African speech AI.' },
  { label: 'Guide a meditation', icon: <SelfImprovement sx={{ fontSize: 16 }} />, text: 'Take a deep breath in… and slowly release. You are safe. You are present.' },
];

export default function SynthesizeComponent() {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const location = useLocation();
  const { userId, balance, refreshBalance } = useStudioUser();

  const [text, setText] = useState('');
  const [file, setFile] = useState(null);
  const [selectedSpeaker, setSelectedSpeaker] = useState(NEURAL_SPEAKERS[0]);
  const [outputLang, setOutputLang] = useState(NEURAL_SPEAKERS[0].lang);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [audioUrl, setAudioUrl] = useState(null);

  useEffect(() => {
    const voiceId = location.state?.voiceId;
    if (!voiceId) return;
    const speaker = NEURAL_SPEAKERS.find((s) => s.id === voiceId);
    if (speaker) {
      setSelectedSpeaker(speaker);
      setOutputLang(speaker.lang);
    }
  }, [location.state?.voiceId]);

  const estimatedCost = text.trim()
    ? Math.max(Math.round(text.length * TTS_RATE * 100) / 100, 0.01)
    : file
      ? Math.max(Math.round((file.size / 3000) * TTS_RATE * 3000 * 100) / 100, 0.01)
      : 0;

  const resolveAudioUrl = async (docId, lang) => {
    const voiceData = await ttsAPI.getVocifyVoice(docId);
    const path =
      voiceData.entries?.[0]?.translations_with_tts?.[lang]?.audio_file_path ||
      voiceData.entries?.[0]?.audio_file_path ||
      voiceData.audio_url;
    if (path) setAudioUrl(path);
  };

  const handleGenerate = async () => {
    if (!userId) {
      setError('Please log in to use text-to-speech');
      return;
    }
    setError(null);
    setLoading(true);
    setAudioUrl(null);
    try {
      if (text.trim()) {
        if (text.length > 5000) throw new Error('Text exceeds 5000 character limit');
        const res = await ttsAPI.synthesizeText(text, selectedSpeaker.id, outputLang, userId);
        if (res.audio_file_url) {
          setAudioUrl(res.audio_file_url);
        } else if (res.doc_id) {
          await resolveAudioUrl(res.doc_id, outputLang);
        } else {
          throw new Error('No audio received');
        }
      } else if (file) {
        if (file.size > 10 * 1024 * 1024) throw new Error('File must be under 10MB');
        const res = await ttsAPI.translateDocumentWithTTS(
          file,
          outputLang,
          [outputLang],
          selectedSpeaker.id,
          userId
        );
        if (res.doc_id) await resolveAudioUrl(res.doc_id, outputLang);
        else throw new Error('No document ID received');
      } else {
        throw new Error('Enter text or upload a document');
      }
      refreshBalance();
      window.dispatchEvent(new CustomEvent('refresh-balance'));
      window.dispatchEvent(new CustomEvent('library-updated'));
    } catch (e) {
      if (e.response?.status === 402) {
        window.dispatchEvent(
          new CustomEvent('subscription-limit-exceeded', {
            detail: { message: e.response?.data?.detail || 'Insufficient credits.', status: 402 },
          })
        );
        setError(e.response?.data?.detail || 'Insufficient credits.');
      } else {
        setError(getFriendlyErrorMessage(e, 'Generation failed. Please try again.'));
      }
    } finally {
      setLoading(false);
    }
  };

  const settingsContent = (
    <ElevenLabsSettingsPanel sx={{ border: 'none', boxShadow: 'none', borderRadius: 0 }}>
      <SettingSection title="Voice">
        <SettingSelect
          label="Speaker"
          value={selectedSpeaker.id}
          onChange={(e) => {
            const speaker = NEURAL_SPEAKERS.find((s) => s.id === e.target.value);
            if (speaker) {
              setSelectedSpeaker(speaker);
              setOutputLang(speaker.lang);
            }
          }}
          options={NEURAL_SPEAKERS.map((v) => ({
            value: v.id,
            label: `${v.name} (${v.lang.toUpperCase()})`,
          }))}
        />
        <SettingSelect
          label="Language"
          value={outputLang}
          onChange={(e) => {
            setOutputLang(e.target.value);
            const speaker = NEURAL_SPEAKERS.find((s) => s.lang === e.target.value);
            if (speaker) setSelectedSpeaker(speaker);
          }}
          options={NEURAL_LANGUAGES.filter((l) => l.code !== 'all').map((l) => ({
            value: l.code,
            label: l.name,
          }))}
        />
      </SettingSection>
      <PropertySection title="Credits" defaultOpen={false}>
        <PropertyRow label="Balance" value={balance !== null ? balance.toFixed(2) : '…'} />
        <PropertyRow label="Estimated" value={`${estimatedCost.toFixed(2)} credits`} />
      </PropertySection>
      <Box sx={{ px: 3, pb: 3 }}>
        <ElevenLabsButton
          variant="contained"
          fullWidth
          size="large"
          loading={loading}
          disabled={(!text.trim() && !file) || (balance !== null && balance < estimatedCost)}
          onClick={handleGenerate}
        >
          Generate speech
        </ElevenLabsButton>
      </Box>
    </ElevenLabsSettingsPanel>
  );

  return (
    <>
      <StudioPageShell
        data-tour="tts-editor"
        icon={<VolumeUp sx={{ fontSize: 22 }} />}
        title="Text to Speech"
        subtitle="Convert text or documents into natural speech"
        settingsContent={settingsContent}
        showPropertiesPanel={!isMobile}
        bottomBar={
          <StudioPlayerBar
            voiceName={selectedSpeaker.name}
            voiceLang={selectedSpeaker.lang}
            audioUrl={audioUrl}
            disabled={!audioUrl}
            onDownload={() => {
              if (!audioUrl) return;
              const link = document.createElement('a');
              link.href = audioUrl;
              link.download = 'synthesis.mp3';
              link.target = '_blank';
              document.body.appendChild(link);
              link.click();
              document.body.removeChild(link);
            }}
          />
        }
        footer={
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, flexWrap: 'wrap' }}>
            <Typography sx={{ fontSize: '0.8125rem', color: '#999' }}>Or upload a document</Typography>
            <ElevenLabsFileUpload
              onFileSelect={setFile}
              selectedFile={file}
              onClearFile={() => setFile(null)}
              accept=".pdf,.doc,.docx,.txt"
            />
            {text.length > 0 && (
              <Typography sx={{ fontSize: '0.75rem', color: '#999', ml: 'auto' }}>
                {text.length} characters
              </Typography>
            )}
          </Box>
        }
      >
        <StudioJobProgressBar open={loading} message="Generating speech…" submessage="Synthesizing audio from your text" />
        <TextField
          multiline
          minRows={12}
          placeholder="Start typing here or paste any text you want to turn into lifelike speech..."
          value={text}
          onChange={(e) => setText(e.target.value)}
          fullWidth
          variant="standard"
          InputProps={{ disableUnderline: true }}
          sx={{
            '& .MuiInputBase-root': { fontSize: '1rem', lineHeight: 1.7, color: '#1a1a1a' },
            '& .MuiInputBase-input::placeholder': { color: '#bbb', opacity: 1 },
          }}
        />
        <Box sx={{ mt: 4 }}>
          <Typography sx={{ fontSize: '0.8125rem', fontWeight: 600, color: '#666', mb: 1.5 }}>
            Get started with
          </Typography>
          <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
            {QUICK_PROMPTS.map((prompt) => (
              <Chip
                key={prompt.label}
                icon={prompt.icon}
                label={prompt.label}
                onClick={() => setText(prompt.text)}
                sx={{
                  fontSize: '0.8125rem',
                  fontWeight: 500,
                  bgcolor: '#fff',
                  border: '1px solid #e8e8e8',
                  borderRadius: '999px',
                  height: 36,
                  '&:hover': { bgcolor: 'rgba(232,160,32,0.06)', borderColor: '#E8A020' },
                }}
              />
            ))}
          </Box>
        </Box>
        <StudioHistorySection sourceId="tts" />
      </StudioPageShell>

      {error && (
        <Alert severity="error" onClose={() => setError(null)} sx={{ position: 'fixed', bottom: 88, right: 24, zIndex: 9999, borderRadius: '8px' }}>
          {error}
        </Alert>
      )}
    </>
  );
}
