import React, { useState, useEffect, useRef } from 'react';
import {
  Box,
  Typography,
  TextField,
  Alert,
  LinearProgress,
  useTheme,
  useMediaQuery,
} from '@mui/material';
import { VideoLibrary, CloudUpload, Translate } from '@mui/icons-material';
import {
  ElevenLabsButton,
  ElevenLabsFileUpload,
  SettingSelect,
  SettingToggle,
  ElevenLabsSettingsPanel,
  SettingSection,
  PropertySection,
  PropertyRow,
} from '../ElevenLabsUI';
import StudioPageShell from '../Layout/StudioPageShell';
import StudioHistorySection from '../Layout/StudioHistorySection';
import { videoAPI, translationAPI, getFriendlyErrorMessage, BASE_URL } from '../../services/api';
import { NEURAL_LANGUAGES, NEURAL_SPEAKERS } from '../../constants/neural_config';
import useStudioUser from '../../hooks/useStudioUser';
import { StudioJobProgressBar } from '../progress';

const PHASE = {
  IDLE: 'idle',
  PROCESSING: 'processing',
  SEGMENTS: 'segments',
  EXPORTING: 'exporting',
  DONE: 'done',
};

export default function VideoDubbingElevenLabs({ userId: userIdProp }) {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const { userId: hookUserId, balance } = useStudioUser();
  const userId = userIdProp || hookUserId;

  const [phase, setPhase] = useState(PHASE.IDLE);
  const [videoFile, setVideoFile] = useState(null);
  const [videoUrl, setVideoUrl] = useState(null);
  const [videoDuration, setVideoDuration] = useState(0);
  const [sourceLang, setSourceLang] = useState('en');
  const [targetLang, setTargetLang] = useState('lg');
  const [selectedVoice, setSelectedVoice] = useState(NEURAL_SPEAKERS[0].id);
  const [burnSubtitles, setBurnSubtitles] = useState(false);
  const [docId, setDocId] = useState(null);
  const [segments, setSegments] = useState([]);
  const [finalVideoUrl, setFinalVideoUrl] = useState(null);
  const [exportProgress, setExportProgress] = useState(0);
  const [error, setError] = useState(null);
  const dubPollRef = useRef(null);

  const stopDubPoll = () => {
    if (dubPollRef.current) {
      clearInterval(dubPollRef.current);
      dubPollRef.current = null;
    }
  };

  useEffect(() => () => stopDubPoll(), []);

  const handleVideoSelect = (file) => {
    if (videoUrl) URL.revokeObjectURL(videoUrl);
    const url = URL.createObjectURL(file);
    setVideoFile(file);
    setVideoUrl(url);
    setSegments([]);
    setDocId(null);
    setFinalVideoUrl(null);
    setPhase(PHASE.IDLE);
    const vid = document.createElement('video');
    vid.preload = 'metadata';
    vid.onloadedmetadata = () => setVideoDuration(vid.duration || 0);
    vid.src = url;
  };

  const pollSegments = (did) =>
    new Promise((resolve, reject) => {
      const started = Date.now();
      const iv = setInterval(async () => {
        if (Date.now() - started > 2 * 60 * 1000) {
          clearInterval(iv);
          reject(new Error('Transcription timed out'));
          return;
        }
        try {
          const data = await videoAPI.getVideo(did);
          const entry = (data.entries || []).find((e) => e.doc_id === did) || data.entries?.[0];
          const transcriptions = entry?.timestamped_transcriptions;
          if (Array.isArray(transcriptions) && transcriptions.length > 0) {
            clearInterval(iv);
            resolve(
              transcriptions.map((s) => ({
                ...s,
                translated: '',
                voice: selectedVoice,
                lang: targetLang,
              }))
            );
          }
        } catch {
          /* retry */
        }
      }, 3000);
    });

  const pollJobDocId = (jobId) =>
    new Promise((resolve, reject) => {
      const started = Date.now();
      const iv = setInterval(async () => {
        if (Date.now() - started > 30 * 60 * 1000) {
          clearInterval(iv);
          reject(new Error('Processing timed out'));
          return;
        }
        try {
          const job = await videoAPI.getJobStatus(jobId);
          if (job.status === 'completed' && job.result?.doc_id) {
            clearInterval(iv);
            resolve(job.result.doc_id);
          } else if (job.status === 'failed') {
            clearInterval(iv);
            reject(new Error(job.error || 'Processing failed'));
          }
        } catch (e) {
          /* retry */
        }
      }, 3000);
    });

  const handleProcess = async () => {
    if (!videoFile || !userId) return;
    setError(null);
    setPhase(PHASE.PROCESSING);
    try {
      const res = await videoAPI.extractAudioFromVideo(videoFile, sourceLang, userId);
      let did = res.doc_id;
      if (res.job_id) did = await pollJobDocId(res.job_id);
      if (!did) throw new Error('No document ID returned');
      setDocId(did);
      const segs = await pollSegments(did);
      setSegments(segs);
      setPhase(PHASE.SEGMENTS);
    } catch (e) {
      setError(getFriendlyErrorMessage(e, 'Failed to process video'));
      setPhase(PHASE.IDLE);
    }
  };

  const handleTranslateAll = async () => {
    if (!userId || !segments.length) return;
    setPhase(PHASE.PROCESSING);
    setError(null);
    try {
      const translated = await Promise.all(
        segments.map(async (seg) => {
          try {
            const response = await translationAPI.translateText(seg.text, sourceLang, [targetLang], userId);
            const chunks = response[targetLang] || [];
            const text = chunks[0]?.text || (typeof chunks[0] === 'string' ? chunks[0] : seg.text);
            return { ...seg, translated: text, voice: selectedVoice, lang: targetLang };
          } catch {
            return { ...seg, translated: seg.text, voice: selectedVoice, lang: targetLang };
          }
        })
      );
      setSegments(translated);
      setPhase(PHASE.SEGMENTS);
    } catch (e) {
      setError(getFriendlyErrorMessage(e, 'Translation failed'));
      setPhase(PHASE.SEGMENTS);
    }
  };

  const pollDubbingJob = (jobId) => {
    stopDubPoll();
    dubPollRef.current = setInterval(async () => {
      try {
        const job = await videoAPI.getJobStatus(jobId);
        setExportProgress(Number.isFinite(job.progress) ? job.progress : 0);
        if (job.status === 'completed' && job.result?.dubbed_video_url) {
          setFinalVideoUrl(job.result.dubbed_video_url);
          setPhase(PHASE.DONE);
          stopDubPoll();
          window.dispatchEvent(new CustomEvent('library-updated'));
        } else if (job.status === 'failed') {
          setError(job.error || 'Export failed');
          setPhase(PHASE.SEGMENTS);
          stopDubPoll();
        }
      } catch {
        /* retry */
      }
    }, 3000);
  };

  const handleExport = async () => {
    if (!docId || !videoFile || !userId || !segments.length) return;
    setError(null);
    setPhase(PHASE.EXPORTING);
    setExportProgress(5);
    try {
      const res = await videoAPI.finalizeDubbing(
        docId,
        segments.map((s, i) => ({
          segment_index: i,
          text: s.translated || s.text,
          target_lang: s.lang || targetLang,
          speaker_id: s.voice || selectedVoice,
          start_time_ms: (s.start_time || 0) * 1000,
          end_time_ms: (s.end_time || 0) * 1000,
        })),
        userId,
        videoFile,
        {
          videoDurationMins: videoDuration / 60,
          originalVolume: 0,
          burnSubtitles,
          trimStartMs: 0,
          trimEndMs: Math.round(videoDuration * 1000),
        }
      );
      if (res?.job_id) {
        pollDubbingJob(res.job_id);
        return;
      }
      if (res.dubbed_video_url) {
        setFinalVideoUrl(res.dubbed_video_url);
        setPhase(PHASE.DONE);
        window.dispatchEvent(new CustomEvent('library-updated'));
      }
    } catch (e) {
      setError(getFriendlyErrorMessage(e, 'Export failed'));
      setPhase(PHASE.SEGMENTS);
    }
  };

  const updateSegment = (index, field, value) => {
    setSegments((prev) => {
      const next = [...prev];
      next[index] = { ...next[index], [field]: value };
      return next;
    });
  };

  const langOptions = NEURAL_LANGUAGES.filter((l) => l.code !== 'all').map((l) => ({
    value: l.code,
    label: l.name,
  }));

  const voiceOptions = NEURAL_SPEAKERS.filter((s) => s.lang === targetLang || targetLang === 'en').length
    ? NEURAL_SPEAKERS.filter((s) => s.lang === targetLang)
    : NEURAL_SPEAKERS;

  const busy = phase === PHASE.PROCESSING || phase === PHASE.EXPORTING;
  const progressMessage =
    phase === PHASE.EXPORTING ? 'Rendering dubbed video…' : 'Processing video…';
  const progressSubmessage =
    phase === PHASE.EXPORTING
      ? exportProgress > 0
        ? `${Math.round(exportProgress)}% complete`
        : 'Mixing audio and subtitles'
      : 'Transcribing and preparing segments';
  const canTranslate = segments.length > 0 && phase !== PHASE.EXPORTING;
  const canExport = segments.some((s) => s.translated || s.text);

  const settingsContent = (
    <ElevenLabsSettingsPanel sx={{ border: 'none', boxShadow: 'none', borderRadius: 0 }}>
      <SettingSection title="Languages">
        <SettingSelect
          label="Source language"
          value={sourceLang}
          onChange={(e) => setSourceLang(e.target.value)}
          options={langOptions}
        />
        <SettingSelect
          label="Target language"
          value={targetLang}
          onChange={(e) => {
            setTargetLang(e.target.value);
            const match = NEURAL_SPEAKERS.find((s) => s.lang === e.target.value);
            if (match) setSelectedVoice(match.id);
          }}
          options={langOptions}
        />
      </SettingSection>
      <SettingSection title="Voice">
        <SettingSelect
          label="Speaker"
          value={selectedVoice}
          onChange={(e) => setSelectedVoice(e.target.value)}
          options={voiceOptions.map((v) => ({
            value: v.id,
            label: `${v.name} (${v.lang.toUpperCase()})`,
          }))}
        />
      </SettingSection>
      <SettingSection title="Export">
        <SettingToggle
          label="Burn subtitles"
          checked={burnSubtitles}
          onChange={(e) => setBurnSubtitles(e.target.checked)}
          description="Embed subtitles in the exported video"
        />
      </SettingSection>
      <PropertySection title="Account" defaultOpen={false}>
        <PropertyRow label="Credits" value={balance !== null ? balance.toFixed(2) : '…'} />
        <PropertyRow label="Segments" value={String(segments.length)} />
      </PropertySection>
      <Box sx={{ px: 3, pb: 3, display: 'flex', flexDirection: 'column', gap: 1.5 }}>
        <ElevenLabsButton
          variant="contained"
          fullWidth
          disabled={!videoFile || busy}
          loading={phase === PHASE.PROCESSING && !segments.length}
          onClick={handleProcess}
        >
          {segments.length ? 'Re-process video' : 'Process video'}
        </ElevenLabsButton>
        <ElevenLabsButton
          variant="outlined"
          fullWidth
          disabled={!canTranslate || busy}
          startIcon={<Translate />}
          onClick={handleTranslateAll}
        >
          Translate all
        </ElevenLabsButton>
        <ElevenLabsButton
          variant="contained"
          fullWidth
          disabled={!canExport || busy}
          loading={phase === PHASE.EXPORTING}
          onClick={handleExport}
        >
          Export dubbed video
        </ElevenLabsButton>
      </Box>
    </ElevenLabsSettingsPanel>
  );

  const previewUrl = finalVideoUrl || videoUrl;

  return (
    <>
      <StudioPageShell
        icon={<VideoLibrary sx={{ fontSize: 22 }} />}
        title="Video dubbing"
        subtitle="Upload a video, transcribe, translate, and export with a new voice"
        maxWidth={1040}
        settingsContent={settingsContent}
        showPropertiesPanel={!isMobile}
      >
        <StudioJobProgressBar
          open={busy}
          message={progressMessage}
          submessage={progressSubmessage}
          progress={phase === PHASE.EXPORTING && exportProgress > 0 ? exportProgress : undefined}
        />
        {!videoFile ? (
          <Box
            sx={{
              border: '2px dashed #e8e8e8',
              borderRadius: '16px',
              bgcolor: '#fafafa',
              p: { xs: 3, md: 5 },
              textAlign: 'center',
            }}
          >
            <CloudUpload sx={{ fontSize: 32, color: '#E8A020', mb: 1 }} />
            <Typography sx={{ fontWeight: 600, mb: 2 }}>Upload your video</Typography>
            <ElevenLabsFileUpload
              onFileSelect={handleVideoSelect}
              selectedFile={videoFile}
              onClearFile={() => {
                if (videoUrl) URL.revokeObjectURL(videoUrl);
                setVideoFile(null);
                setVideoUrl(null);
                setSegments([]);
              }}
              accept="video/*"
            />
          </Box>
        ) : (
          <Box
            sx={{
              borderRadius: '12px',
              overflow: 'hidden',
              bgcolor: '#000',
              aspectRatio: '16/9',
              maxHeight: 360,
              mb: 3,
            }}
          >
            <video
              src={previewUrl}
              controls
              style={{ width: '100%', height: '100%', objectFit: 'contain' }}
            />
          </Box>
        )}

        {phase === PHASE.EXPORTING && exportProgress > 0 && (
          <Box sx={{ mb: 2 }}>
            <LinearProgress variant="determinate" value={exportProgress} sx={{ height: 6, borderRadius: 3 }} />
            <Typography sx={{ fontSize: '0.75rem', color: '#999', mt: 0.5 }}>
              Exporting… {Math.round(exportProgress)}%
            </Typography>
          </Box>
        )}

        {segments.length > 0 && (
          <Box>
            <Typography sx={{ fontSize: '0.8125rem', fontWeight: 600, color: '#666', mb: 1.5, textTransform: 'uppercase', letterSpacing: '0.06em' }}>
              Transcript segments ({segments.length})
            </Typography>
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5, maxHeight: 420, overflowY: 'auto' }}>
              {segments.map((seg, i) => (
                <Box
                  key={i}
                  sx={{
                    border: '1px solid #e8e8e8',
                    borderRadius: '10px',
                    p: 2,
                    bgcolor: '#fff',
                  }}
                >
                  <Typography sx={{ fontSize: '0.75rem', color: '#999', mb: 1 }}>
                    {seg.start_time?.toFixed(1)}s – {seg.end_time?.toFixed(1)}s
                  </Typography>
                  <Typography sx={{ fontSize: '0.8125rem', color: '#666', mb: 1 }}>{seg.text}</Typography>
                  <TextField
                    fullWidth
                    size="small"
                    multiline
                    minRows={2}
                    placeholder="Translation…"
                    value={seg.translated || ''}
                    onChange={(e) => updateSegment(i, 'translated', e.target.value)}
                    sx={{ '& .MuiOutlinedInput-root': { fontSize: '0.875rem', borderRadius: '8px' } }}
                  />
                </Box>
              ))}
            </Box>
          </Box>
        )}

        <StudioHistorySection sourceId="dubbing" />
      </StudioPageShell>

      {error && (
        <Alert severity="error" onClose={() => setError(null)} sx={{ position: 'fixed', bottom: 24, right: 24, zIndex: 9999, borderRadius: '8px' }}>
          {error}
        </Alert>
      )}
    </>
  );
}
